import { icon } from './icons.js';
import { textFonts, textValue, textHeight } from './text-style.js';

const esc = (v = '') => String(v).replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c]));
const btn = (name, title, action, cls = '') => `<button class="icon-button ${cls}" title="${esc(title)}" aria-label="${esc(title)}" data-action="${action}">${icon(name)}</button>`;
const brand = `<span class="brand-mark">${icon('target')}</span><span class="brand-name">aiming<span class="brand-period">.</span></span>`;

function textPreview(c) {
  const size=c.fontSize||24,padding=c.textBackground?10:4;
  const columns=Math.max(1,Math.floor((c.width-padding*2)/(size*.56)));
  const lines=textValue(c).slice(0,1600).split('\n').flatMap(line=>{const rows=[];for(let i=0;i<Math.max(1,line.length);i+=columns)rows.push(line.slice(i,i+columns));return rows;}).slice(0,40);
  const x=c.textAlign==='center'?c.x+c.width/2:c.textAlign==='right'?c.x+c.width-padding:c.x+padding;
  const anchor=c.textAlign==='center'?'middle':c.textAlign==='right'?'end':'start';
  return `<g>${c.textBackground?`<rect x="${c.x}" y="${c.y}" width="${c.width}" height="${textHeight(c)}" rx="4" fill="${esc(c.color)}"/>`:''}<text x="${x}" y="${c.y+padding+size}" font-family="${esc(textFonts[c.fontFamily]||textFonts.sans)}" font-size="${size}" font-weight="${c.bold?700:400}" font-style="${c.italic?'italic':'normal'}" text-decoration="${c.underline?'underline':'none'}" text-anchor="${anchor}" fill="${esc(c.textColor||'#424b3c')}">${lines.map((line,i)=>`<tspan x="${x}" dy="${i?size*1.35:0}">${esc(line)}</tspan>`).join('')}</text></g>`;
}

function preview(b) {
  if (!b.cards.length) return `<svg viewBox="0 0 640 300" aria-hidden="true"><rect x="252" y="94" width="136" height="112" rx="6" fill="#fff1ad" transform="rotate(-7 320 150)"/><path d="M294 144h52m-26-26v52" stroke="#c6b967" stroke-width="2"/></svg>`;
  const minX = Math.min(...b.cards.map(c=>c.x))-45, minY = Math.min(...b.cards.map(c=>c.y))-45;
  const maxX = Math.max(...b.cards.map(c=>c.x+c.width))+45, maxY = Math.max(...b.cards.map(c=>c.y+(c.type==='text'?textHeight(c):c.height||210)))+45;
  return `<svg viewBox="${minX} ${minY} ${maxX-minX} ${maxY-minY}" aria-hidden="true">${b.cards.slice(0,100).map(c=>c.type==='text'?textPreview(c):`<g><rect x="${c.x}" y="${c.y}" width="${c.width}" height="${c.height||210}" rx="8" fill="${esc(c.color)}" stroke="#c7ccbf" stroke-width="1.2"/>${c.type==='image'&&c.src?`<image href="${esc(c.src)}" x="${c.x+12}" y="${c.y+44}" width="${c.width-24}" height="${Math.max(50,(c.height||210)-70)}" preserveAspectRatio="xMidYMid slice"/>`:`<path d="M${c.x+22} ${c.y+38}h${Math.min(c.width-44,125)}m-${Math.min(c.width-44,125)} 25h${c.width-44}m-${c.width-44} 18h${Math.max(40,c.width-70)}" stroke="#65715b" opacity=".22" stroke-width="6" stroke-linecap="round"/>`}</g>`).join('')}</svg>`;
}

export function homeCards(workspace, { filter='all', query='', sort='recent' } = {}) {
  const q=query.trim().toLocaleLowerCase('it');
  const boards=workspace.boards.filter(b=>(filter!=='favorites'||b.favorite)&&(!q||[b.name,b.description,...b.cards.map(c=>[c.title,c.content,c.category,...(c.tasks||[]).map(t=>t.text)].join(' '))].join(' ').toLocaleLowerCase('it').includes(q)));
  boards.sort(sort==='name'?(a,b)=>a.name.localeCompare(b.name,'it'):(a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt));
  const cards=boards.map(b=>`<article class="home-board"><button class="home-board-open" data-board="${b.id}" aria-label="Apri ${esc(b.name)}"><div class="home-board-art">${preview(b)}</div><div class="home-board-copy"><h3>${esc(b.name)}</h3><p>${esc(b.description||`${b.cards.length} card · Uno spazio tutto tuo`)}</p></div></button><div class="home-board-footer"><span class="home-board-date">${b.cards.length} card <span>·</span> ${new Intl.DateTimeFormat('it',{day:'numeric',month:'short'}).format(new Date(b.updatedAt))}</span><div class="home-board-tools"><button class="icon-button ${b.favorite?'is-favorite':''}" data-favorite-board="${b.id}" aria-label="${b.favorite?'Rimuovi':'Aggiungi'} ${esc(b.name)} ${b.favorite?'dai':'ai'} preferiti" aria-pressed="${!!b.favorite}" title="${b.favorite?'Rimuovi dai preferiti':'Aggiungi ai preferiti'}">${icon('star')}</button><button class="icon-button" data-options-board="${b.id}" aria-label="Opzioni ${esc(b.name)}" title="Opzioni lavagna">${icon('more')}</button></div></div></article>`).join('');
  const empty=!boards.length?`<div class="home-empty">${icon(filter==='favorites'?'star':'search')}<h3>${q?'Nessuna lavagna trovata.':filter==='favorites'?'Le tue preferite, tutte qui.':'Spazio a una nuova idea.'}</h3><p>${q?'Prova un’altra parola.':filter==='favorites'?'Aggiungi una lavagna ai preferiti usando la stellina.':'Crea la tua prima lavagna e comincia a scrivere.'}</p></div>`:'';
  return cards+empty+(!q&&filter!=='favorites'?`<button class="home-create-card" data-action="new-board"><span>${icon('plus')}</span><strong>Una nuova possibilità</strong><small>Crea una lavagna vuota</small></button>`:'');
}

export function homeMarkup(workspace, options, saveHTML) {
  return `<main class="home-page"><header class="home-header"><a href="#" class="brand" data-action="boards" aria-label="Aiming, home">${brand}</a><div class="home-header-actions"><span class="save-status" role="status">${saveHTML}</span><button class="button secondary" data-action="backup" aria-label="Backup e ripristino">${icon('lock')}<span class="button-label">Backup e ripristino</span></button><button class="button secondary" data-action="settings" aria-label="Impostazioni">${icon('settings')}<span class="button-label">Impostazioni</span></button>${btn('help','Guida e scorciatoie','help')}</div></header><div class="home-content"><section class="home-welcome"><span class="eyebrow">IL TUO ANGOLO CREATIVO</span><h1>Ogni idea merita<br>il suo <span>spazio.</span></h1><p>Raccogli i pensieri. Trova le connessioni. Segui la tua direzione.</p></section><div class="home-heading-row"><div><h2>Le tue lavagne</h2><p>Tutto quello che hai in mente, in un solo posto.</p></div><button class="button primary" data-action="new-board">${icon('plus')}Nuova lavagna</button></div><div class="home-controls"><nav class="home-tabs" aria-label="Filtra lavagne"><button class="home-tab ${options.filter==='all'?'active':''}" data-home-filter="all" aria-pressed="${options.filter==='all'}">${icon('grid')}Tutte le lavagne <span>${workspace.boards.length}</span></button><button class="home-tab ${options.filter==='favorites'?'active':''}" data-home-filter="favorites" aria-pressed="${options.filter==='favorites'}">${icon('star')}Preferite <span>${workspace.boards.filter(b=>b.favorite).length}</span></button></nav><label class="home-search">${icon('search')}<input id="home-search" aria-label="Cerca nelle tue lavagne" placeholder="Cerca una lavagna o un’idea…" value="${esc(options.query)}"></label><label class="home-sort"><select id="home-sort" aria-label="Ordina lavagne"><option value="recent" ${options.sort==='recent'?'selected':''}>Ultima modifica</option><option value="name" ${options.sort==='name'?'selected':''}>Nome A–Z</option></select></label></div><section class="home-gallery" id="home-gallery" aria-label="Le tue lavagne">${homeCards(workspace,options)}</section></div><footer class="home-footer"><span>${icon('shield')}Le tue idee restano su questo dispositivo.</span><button data-action="search">Cerca in tutti i contenuti <kbd>Ctrl / ⌘ K</kbd></button></footer></main>`;
}

export function boardMarkup(workspace, b, cardsHTML, toolsHTML, saveHTML, canUndo, canRedo) {
  return `<main class="board-fullscreen"><section class="canvas-shell grid-${workspace.settings?.grid||'dots'}" aria-label="Lavagna infinita" style="--canvas-bg:${esc(workspace.settings?.background||'#f8f9f7')}"><div class="canvas" id="canvas" tabindex="0" aria-label="Area di lavoro. Scrivi direttamente nelle card e trascina il bordo per spostarle."><div class="world" id="world"><svg class="connections" id="connections" aria-hidden="true"><defs><marker id="arrowhead" markerWidth="8" markerHeight="8" refX="6" refY="4" orient="auto"><path d="M1 1L6 4L1 7" fill="none" stroke="#b2b4ac" stroke-width="1.4"/></marker></defs><g id="connection-paths"></g></svg><div id="cards">${cardsHTML}</div></div>${!b.cards.length?`<div class="canvas-empty"><button class="button primary" data-action="add-note">${icon('plus')}Aggiungi un post-it</button><p>Doppio clic per scrivere dove vuoi.</p></div>`:''}</div><nav class="board-top-left" aria-label="Navigazione lavagna">${btn('back','Torna alle lavagne','boards','back-home')}<span class="divider"></span><button class="board-name-chip" data-action="rename-board" title="Rinomina lavagna">${esc(b.name)}</button><button class="board-star ${b.favorite?'is-favorite':''}" data-action="favorite" title="${b.favorite?'Rimuovi dai preferiti':'Aggiungi ai preferiti'}" aria-label="${b.favorite?'Rimuovi dai preferiti':'Aggiungi ai preferiti'}" aria-pressed="${!!b.favorite}">${icon('star')}</button>${btn('more','Opzioni lavagna','board-menu')}</nav><div class="board-top-right"><span class="save-status" role="status">${saveHTML}</span>${btn('download','Backup e ripristino','backup')}${btn('search','Cerca in tutte le lavagne','search')}${btn('settings','Impostazioni','settings')}</div><div class="floating-tools" role="toolbar" aria-label="Strumenti lavagna">${toolsHTML}</div><div class="selection-bar hidden" id="selection-bar" role="toolbar" aria-label="Personalizza card"></div><div class="canvas-hint">${icon('hand')}<span>Trascina lo sfondo · Ctrl + rotella per lo zoom</span></div><div class="zoom-controls">${btn('undo','Annulla (Ctrl+Z)','undo',canUndo?'':'is-disabled')}${btn('redo','Ripeti (Ctrl+Shift+Z)','redo',canRedo?'':'is-disabled')}<span class="divider"></span>${btn('minus','Riduci zoom','zoom-out')}<button class="zoom-value" data-action="reset-zoom" title="Ripristina zoom al 100%">100%</button>${btn('plus','Aumenta zoom','zoom-in')}<span class="divider"></span>${btn('fit','Adatta allo schermo (F)','fit')}</div><aside class="minimap" id="minimap" aria-label="Minimappa della lavagna"><header class="minimap-header"><span>Minimappa</span><div><button class="icon-button" type="button" data-map-action="fit" title="Mostra tutta la lavagna" aria-label="Mostra tutta la lavagna">${icon('fit')}</button><button class="icon-button" type="button" data-map-toggle aria-expanded="false" aria-label="Espandi minimappa">${icon('chevron')}</button></div></header><div class="minimap-stage"><svg id="minimap-svg" viewBox="0 0 320 180" tabindex="0" role="group" aria-roledescription="minimappa interattiva" aria-label="Naviga nella lavagna: clicca o trascina; usa le frecce per spostarti"></svg></div><footer class="minimap-footer"><span>Clicca o trascina per spostarti</span><div><button class="icon-button" type="button" data-map-action="out" aria-label="Riduci zoom dalla minimappa">${icon('minus')}</button><span data-map-zoom>100%</span><button class="icon-button" type="button" data-map-action="in" aria-label="Aumenta zoom dalla minimappa">${icon('plus')}</button></div></footer></aside>${btn('help','Guida e scorciatoie','help','canvas-help')}</section></main>`;
}
